// Public = static assets (CSS/JS), login page, auth endpoints
const _PUBLIC_PATHS    = new Set(['/login', '/login.html', '/robots.txt', '/favicon.ico', '/favicon.svg', '/favicon.png', '/manifest.json', '/icon-192.png', '/icon-512.png', '/healthz', '/api/ticker', '/api/pricing', '/api/version',
  '/week-ahead', '/week-ahead.html', '/api/week-ahead', '/api/calendar-events', '/api/week-ahead-news', '/api/mosaic-images',
  '/internal/landing-snapshot', '/api/hero-news', '/api/hero-recaps', '/api/hero-strength', '/api/hero-ticker', '/api/geo', '/actualites', '/sitemap-actualites.xml', '/api/updates-public']);   // page Week Ahead PUBLIQUE + mosaïque login ; + endpoint cron landing (token) ; + fil hero LIVE + recaps analystes + force des devises LIVE de la landing (public + CORS) ; + pages SEO Actualités + leur sitemap dynamique (proxy nginx datatradingpro.com)
const _PUBLIC_PREFIXES = ['/css/', '/js/', '/assets/images/', '/api/auth/', '/api/whop/', '/downloads/', '/actualites/', '/api/email-widget/', '/internal/email-campaign', '/api/unsubscribe', '/api/track/', '/api/v1/'];   // /api/v1/ = API programmatique : le gate SESSION est bypassé mais CHAQUE route v1 exige une CLÉ API (requireApiKey)   // /downloads/ PUBLIC : l'installeur desktop doit etre telechargeable AVANT le login ; /actualites/ = pages SEO ; /api/email-widget/ = images PNG pour les clients mail (elles doivent s afficher sans session). Les PAGES de rendu /internal/email-widget/ ont ete RETIREES du public le 21/08 : elles servaient en clair des widgets vendus par abonnement ; Puppeteer y accede desormais par jeton interne depuis la boucle locale ; /api/unsubscribe = lien de desinscription dans les mails de campagne (doit marcher sans login)

// Jeton d'appel INTERNE (préchauffage → 127.0.0.1) : généré à chaque boot (surclassable via env pour
// le diagnostic), jamais exposé hors process/serveur. Sans lui, les appels locaux du prewarm vers les
// routes protégées prenaient un 401 silencieux.
const _INTERNAL_TOKEN = process.env.DTP_INTERNAL_TOKEN || require('crypto').randomBytes(24).toString('hex');
/* On REPUBLIE le jeton dans l environnement du processus. Les pages de rendu des widgets e-mail ne
   sont plus servies publiquement (elles exposaient en clair des widgets vendus) : Puppeteer doit
   donc s authentifier comme appel interne. Il tourne dans CE processus ; sans cette ligne, un jeton
   tire au hasard au demarrage lui resterait inconnu et toutes les images des e-mails casseraient. */
process.env.DTP_INTERNAL_TOKEN = _INTERNAL_TOKEN;

/* LECTURE SEULE — garde-fou posé le 18/08 après incident RÉEL.
   Un serveur lancé sur un poste de développement pour INSPECTER le desk (banc de rendu, mesure de
   contraste…) se connecte aux VRAIES bases Supabase et aux VRAIS fournisseurs d'e-mail : ses tâches
   de démarrage ont donc écrit en production depuis une machine locale. Constaté ce jour-là : un
   message d'accueil inséré dans la conversation d'un client réel, un e-mail de bienvenue parti, une
   alerte admin envoyée. La campagne (163 contacts) a été ÉVALUÉE au même moment et n'est passée à
   côté que parce que ses verrous hebdomadaires ne s'ouvraient pas à cette heure-là.
   Poser DTP_LECTURE_SEULE=1 neutralise tout ce qui ÉCRIT ou ENVOIE en tâche de fond. La production
   ne définit pas cette variable : son comportement reste strictement identique. */
const _LECTURE_SEULE = /^(1|true|oui)$/i.test(String(process.env.DTP_LECTURE_SEULE || ''));

// Version du build = le ?v= de app.js dans index.html. Exposée à /api/version : le client compare sa
// propre version à celle-ci et, si un nouveau déploiement est détecté, propose un rechargement en
// 1 clic (fini le « pas à jour » quand la session reste ouverte après un déploiement).
const _BOOT_TS = Date.now();   // demarrage du process — sert a prouver qu un deploiement SERVEUR est bien en ligne
let BUILD_VERSION = '';
try { BUILD_VERSION = (fs.readFileSync(path.join(__dirname, 'public', 'index.html'), 'utf8').match(/app\.js\?v=([0-9A-Za-z]+)/) || [])[1] || ''; } catch {}

// Éjection de session (in-memory) : ids d'utilisateurs à déconnecter de force (suspension / bouton admin
// « Déconnecter »). Consulté par requireAuth (appels API) + /api/auth/me (heartbeat du desk ~20 s) → le
// compte est éjecté du desk quasi immédiatement. Un nouveau login légitime lève l'ordre (kick ponctuel).
const _forceLogout = new Set();
// Session UNIQUE par compte (anti-partage d'identifiants) : userId -> jeton de la DERNIÈRE connexion.
// À chaque login CLIENT on génère un jeton neuf → toute session plus ancienne (jeton différent) est éjectée
// (requireAuth + /me). Vidé au redémarrage = contrainte rétablie dès les prochains logins (jamais de
// déconnexion de masse au boot). Staff (admin/support) NON concerné (plusieurs sessions autorisées).
const _sessionEpoch = new Map();
/* Le staff est-il soumis, lui aussi, à la session unique ? OUI par défaut depuis le 21/08 : l'ancienne
   exemption rendait la règle intestable pour qui la vérifiait avec son propre compte (admin). Poser
   DTP_SESSION_UNIQUE_STAFF=0 la rétablit, sans redéploiement, si travailler sur deux postes redevient
   nécessaire. */
const _SESSION_UNIQUE_STAFF = !/^(0|false|non)$/i.test(String(process.env.DTP_SESSION_UNIQUE_STAFF || '1'));
/* ── LA CONTRAINTE SURVIT AUX REDÉMARRAGES (15/08/2026) ─────────────────────────────────────────
   Le registre ne vivait qu'en mémoire : chaque redéploiement le vidait, et deux sessions ouvertes
   sur le MÊME compte pouvaient de nouveau cohabiter jusqu'à la prochaine reconnexion. Mesuré le
   15/08 : une dizaine de déploiements dans la journée, donc autant de fenêtres où le partage
   d'identifiants redevenait possible sans que personne ne le voie.
   Le commentaire d'origine craignait « une déconnexion de masse au boot ». Elle n'a pas lieu : la
   règle ne tue QUE les sessions dont le jeton diffère du DERNIER connu, c'est-à-dire précisément
   celles qui ont été supplantées. La session la plus récente de chaque compte porte le jeton
   enregistré et survit.
   GARDE SUPPLÉMENTAIRE (voir requireAuth) : on n'éjecte que si la session PORTE un jeton. Une
   session antérieure à ce mécanisme n'en a pas ; sans cette garde, la restauration du registre
   l'aurait déconnectée au premier démarrage, ce qui aurait été un vrai effet de bord. */
const _SESS_EPOCH_KV = 'sess:epochs';
let _sessEpochSauveT = null;
/* Ferme les WebSockets d un compte dont le jeton n est plus valide. `garder` = le jeton qui
   survit (celui de la session qui vient d agir), ou null pour tout fermer. */
function _fermerSockets(uid, garder) {
  try {
    if (typeof wss === 'undefined' || !wss.clients) return;
    wss.clients.forEach((c) => {
      if (c._uid === uid && (!garder || c._stoken !== garder)) {
        try { c.close(1008, 'session terminée'); } catch (e) {}
      }
    });
  } catch (e) {}
}

function _sessEpochSauver() {                   // écriture groupée : plusieurs connexions rapprochées = un seul write
  /* ⚠️ JAMAIS EN LECTURE SEULE. Ce registre est PARTAGÉ avec la production : même table `ai_cache`,
     même clé `sess:epochs`. Un serveur lancé sur un poste de développement pour une mesure écrase
     donc la carte des jetons de TOUS les comptes en ligne, et déconnecte en masse des clients qui
     n'ont rien demandé. Le mode lecture seule ne couvrait que les tâches de fond ; cette écriture-ci
     part d'un simple login, y compris un login de test. Le trou est refermé ici. */
  if (_LECTURE_SEULE) return;
  if (_sessEpochSauveT) return;
  _sessEpochSauveT = setTimeout(() => {
    _sessEpochSauveT = null;
    try { auth.aiCacheSet(_SESS_EPOCH_KV, Object.fromEntries(_sessionEpoch)).catch(() => {}); } catch (e) {}
  }, 3000);
}
try {
  auth.aiCacheGet(_SESS_EPOCH_KV).then(o => {
    if (!o || typeof o !== 'object') return;
    let n = 0;
    for (const [k, v] of Object.entries(o)) if (typeof v === 'string' && v) { _sessionEpoch.set(String(k), v); n++; }
    if (n) console.log('[Auth] session unique : ' + n + ' jeton(s) restauré(s) → la contrainte survit au redémarrage');
  }).catch(() => {});
} catch (e) {}

/* ═══ SECOND VERROU : LE PARTAGE DE COOKIE (21/08) ══════════════════════════════════════════════
   Le verrou par jeton ci-dessus se déclenche à un LOGIN. Deux personnes qui se partagent le même
   COOKIE ne se connectent jamais : elles portent le même jeton, et aucune comparaison de jetons ne
   peut les distinguer. C'était la limite assumée du mécanisme, et c'est précisément le cas que la
   demande vise (« qu'on ne puisse pas être deux sur un même compte »).

   On donne donc à chaque NAVIGATEUR un identifiant tiré au sort, conservé dans son `localStorage`.
   Il n'est PAS transporté par un cookie recopié : c'est ce qui permet enfin de séparer deux
   personnes derrière une même session. Le desk l'annonce au chargement ; le dernier à annoncer
   détient le compte, les autres sont éjectés à leur battement suivant (20 s au plus).

   ⚠️ L'ANNONCE SE FAIT AU CHARGEMENT, JAMAIS AU BATTEMENT. Si chaque battement réclamait la
   session, A et B se chasseraient mutuellement toutes les vingt secondes, indéfiniment, sans que
   ni l'un ni l'autre ne puisse travailler. Réclamer est un ÉVÉNEMENT, vérifier est un état.

   ⚠️ SANS IDENTIFIANT, ON N'ÉJECTE PAS. `localStorage` indisponible (navigation privée verrouillée,
   réglage d'entreprise), ancienne version du desk encore en cache : la requête arrive sans
   identifiant. On la laisse passer. Un verrou qui déconnecte faute d'information punit d'abord le
   client légitime, et il le fait sans que personne ne comprenne pourquoi.

   ⚠️ TOUT EN MÉMOIRE, jamais en base : un incident d'egress de 18 To a déjà été payé pour une
   écriture par requête. Un redémarrage remet simplement les compteurs à zéro, et la contrainte se
   rétablit au premier chargement de chaque desk. */
const _sessionDevice = new Map();          // userId -> { dev, ts }
const _DEV_MAX_COMPTES = 5000;             // borne dure : jamais de croissance libre en mémoire
const _RX_DEV = /^[a-z0-9-]{8,64}$/;

/* L'identifiant voyage en en-tête sur les requêtes HTTP, et en paramètre d'URL sur le WebSocket :
   un navigateur ne peut pas poser d'en-tête sur une connexion WebSocket. */
function _devDeLaRequete(req) {
  let d = String((req.headers && req.headers['x-dtp-appareil']) || '').toLowerCase().trim();
  if (!d && req.url && req.url.indexOf('?') >= 0) {
    try { d = String(new URLSearchParams(req.url.split('?')[1]).get('a') || '').toLowerCase().trim(); } catch (e) {}
  }
  return _RX_DEV.test(d) ? d : null;
}

/* Réclamation : ce navigateur-ci devient le détenteur du compte. Renvoie true si la détention a
   CHANGÉ de main (donc s'il y a lieu de couper ce qui reste de l'ancienne). */
function _devReclamer(uid, dev) {
  if (!uid || !dev) return false;
  const av = _sessionDevice.get(uid);
  _sessionDevice.set(uid, { dev, ts: Date.now() });
  if (_sessionDevice.size > _DEV_MAX_COMPTES) {          // purge des plus anciens, borne mémoire
    const tries = [..._sessionDevice.entries()].sort((a, b) => a[1].ts - b[1].ts);
    for (let i = 0; i < tries.length - _DEV_MAX_COMPTES; i++) _sessionDevice.delete(tries[i][0]);
  }
  return !!(av && av.dev !== dev);
}

// ── DÉCONNEXION ABSOLUE À 24 H (demande user 23/07, TOUTES plateformes : web, app Electron, PWA mobile —
//    elles partagent la même session cookie donc le MÊME couperet serveur). Le cookie-session est GLISSANT
//    (chaque visite repousse l'expiration) → sans ancre absolue, un utilisateur actif ne serait jamais
//    déconnecté. Ancre = session.loginAt (posée au login). Session d'AVANT ce déploiement (sans loginAt) :
//    on l'ancre à la première requête → elle expire 24 h plus tard (pas de déconnexion de masse au deploy). ──
const _SESSION_MAX_MS = 24 * 60 * 60 * 1000;
// « RESTER CONNECTÉ » (05/08, retour d'un membre : « il le coche à chaque fois, ça ne marche pas »).
// La case existait dans le formulaire mais n'était JAMAIS lue : ni envoyée par login.html, ni reçue
// par le serveur. Elle promettait donc quelque chose que rien n'implémentait.
// Le couperet de 24 h reste la règle PAR DÉFAUT — c'était une demande explicite (« reconnexion
// quotidienne »). La case le repousse à 30 jours pour CETTE session-là seulement : c'est un choix
// du membre, pas un relâchement général. Décocher, ou se reconnecter sans cocher, ramène à 24 h.
const _SESSION_MAX_LONG_MS = 30 * 24 * 60 * 60 * 1000;
function _sessionMaxMs(req) { return req.session?.remember ? _SESSION_MAX_LONG_MS : _SESSION_MAX_MS; }
function _sessionExpired(req) {
  if (!req.session?.userId) return false;
  if (!req.session.loginAt) { req.session.loginAt = Date.now(); return false; }   // legacy → ancrée maintenant
  return Date.now() - req.session.loginAt > _sessionMaxMs(req);
}

/* Regle d ejection, EXTRAITE de requireAuth pour etre appliquee partout ou elle manquait : au
   WebSocket, et aux routes /api/auth/me/* que le prefixe public exemptait du garde.
   On ne change RIEN a la politique : memes conditions, meme tolerance pour les sessions anterieures
   au mecanisme (celles qui n ont pas de jeton). Une seule definition, donc plus de divergence
   possible entre les endroits ou elle s applique. */
function _sessionMorte(req) {
  if (!req.session || !req.session.userId) return 'absente';
  if (_sessionExpired(req)) return 'expiree';
  const sid = String(req.session.userId);
  if (_forceLogout.has(sid)) return 'deconnectee';
  if (auth.isEmailBlacklisted(req.session.user && req.session.user.email)) return 'blacklistee';
  const ep = _sessionEpoch.get(sid);
  if (ep && req.session.stoken && ep !== req.session.stoken) return 'supplantee';
  /* Second verrou : même session (donc même cookie), mais un AUTRE navigateur l'a réclamée depuis.
     On n'éjecte que si la requête porte un identifiant : sans lui, on ne sait rien, et ne rien
     savoir ne justifie pas de déconnecter quelqu'un. */
  const dv = _sessionDevice.get(sid), mien = _devDeLaRequete(req);
  if (dv && mien && dv.dev !== mien) return 'autre-appareil';
  return null;
}

/* Ferme les WebSockets d'un compte ouverts depuis un AUTRE navigateur que celui qui vient de
   réclamer. Sans cela, l'onglet éjecté continuerait de recevoir le fil temps réel : il verrait le
   produit vivre alors qu'il n'y a plus droit, jusqu'à ce qu'il soit fermé. */
function _fermerSocketsAppareil(uid, garderDev) {
  try {
    if (typeof wss === 'undefined' || !wss.clients) return;
    wss.clients.forEach((c) => {
      if (c._uid === uid && c._dev && c._dev !== garderDev) {
        try { c.close(1008, 'session reprise sur un autre appareil'); } catch (e) {}
      }
    });
  } catch (e) {}
}

/* Garde LOCALE pour les routes sous un prefixe public. requireAuth ne peut pas servir ici : il
   sort en next() des qu il voit /api/auth/, precisement le prefixe de ces routes. */
function _gardeSession(req, res, next) {
  const mort = _sessionMorte(req);
  if (mort) { req.session = null; return res.status(401).json({ error: 'Session terminée', loggedOut: true }); }
  next();
}

/* ── DETECTION DU PARTAGE DE COMPTE (19/08) ──────────────────────────────────────────────────
   Le verrou de session unique ne se declenche qu a un nouveau LOGIN : deux personnes qui se
   partagent le cookie portent le meme jeton et ne sont jamais separees. On les repere autrement,
   par leur EMPREINTE : le reseau /24 et le navigateur. Rien n est ecrit en base (un incident
   d egress de 18 To a deja ete paye ici), et personne n est deconnecte automatiquement : un client
   legitime sur son ordinateur ET son telephone en 4G presente deux reseaux au meme instant.
   L administrateur voit, l administrateur tranche. */
const _empreintes = new Map();              // userId -> Map(empreinte -> dernier vu)
const _EMPR_FENETRE = 12 * 60 * 1000;       // au-dela, une empreinte n est plus « active »
const _EMPR_MAX_COMPTES = 500;              // borne dure : jamais de croissance libre en memoire

function _empreinteDe(req) {
  const ip = _clientIp(req);
  // Reseau plutot qu adresse exacte : un bail DHCP renouvele ne doit pas compter pour un partage.
  const reseau = ip.indexOf(":") >= 0
    ? ip.split(":").slice(0, 3).join(":")
    : ip.split(".").slice(0, 3).join(".");
  const ua = String(req.headers["user-agent"] || "").slice(0, 200);
  let h = 0;
  for (let i = 0; i < ua.length; i++) { h = ((h << 5) - h + ua.charCodeAt(i)) | 0; }
  return reseau + "|" + (h >>> 0).toString(36);
}

function _noterEmpreinte(req) {
  try {
    const uid = String(req.session && req.session.userId || "");
    if (!uid) return;
    let m = _empreintes.get(uid);
    if (!m) {
      if (_empreintes.size >= _EMPR_MAX_COMPTES) return;   // borne atteinte : on n ajoute plus
      m = new Map(); _empreintes.set(uid, m);
    }
    m.set(_empreinteDe(req), Date.now());
    if (m.size > 8) {                                      // borne par compte
      const vieilles = [...m.entries()].sort((a, b) => a[1] - b[1]).slice(0, m.size - 8);
      vieilles.forEach(([k]) => m.delete(k));
    }
  } catch (e) {}
}

/* Comptes vus depuis PLUSIEURS empreintes dans la fenetre. Ce n est pas une preuve de partage :
   c est un signal, a lire avec le nombre de reseaux DISTINCTS, qui est le plus parlant. */
function _comptesPartages() {
  const seuil = Date.now() - _EMPR_FENETRE;
  const out = [];
  for (const [uid, m] of _empreintes) {
    const vives = [...m.entries()].filter(([, t]) => t >= seuil);
    if (vives.length < 2) continue;
    const reseaux = new Set(vives.map(([k]) => k.split("|")[0]));
    out.push({
      userId: uid,
      empreintes: vives.length,
      reseaux: reseaux.size,
      dernier: Math.max(...vives.map(([, t]) => t)),
    });
  }
  // Le plus suspect en tete : plusieurs RESEAUX pese plus que plusieurs navigateurs.
  return out.sort((a, b) => (b.reseaux - a.reseaux) || (b.empreintes - a.empreintes));
}

// Menage : les empreintes mortes ne doivent pas s accumuler.
setInterval(() => {
  const seuil = Date.now() - _EMPR_FENETRE;
  for (const [uid, m] of _empreintes) {
    for (const [k, t] of m) if (t < seuil) m.delete(k);
    if (!m.size) _empreintes.delete(uid);
  }
}, 5 * 60 * 1000);

function requireAuth(req, res, next) {
  // Le DESK ne doit jamais être indexé (app privée) : en-tête posé AVANT le court-circuit des
  // chemins publics : /login est public et sortait avant de recevoir l'en-tête (mesuré en prod).
  if (/^desk\./i.test(req.hostname || '')) res.set('X-Robots-Tag', 'noindex');
  const isPublic = _PUBLIC_PATHS.has(req.path) ||
    _PUBLIC_PREFIXES.some(p => req.path.startsWith(p));
  if (isPublic) return next();

  // Le DESK ne doit jamais être indexé (app privée) : en-tête explicite sur toutes ses réponses.
  // Le robots.txt du desk autorise / et /login : les moteurs peuvent donc LIRE cet en-tête et

  // Appel interne (prewarm) : jeton de boot + socket loopback exigés tous les deux.
  if (req.headers['x-dtp-internal'] === _INTERNAL_TOKEN && /^(::1|127\.0\.0\.1|::ffff:127\.0\.0\.1)$/.test(req.socket.remoteAddress || '')) return next();

  if (req.session?.userId && _sessionExpired(req)) {
    req.session = null;   // couperet 24 h → reconnexion exigée (toutes plateformes)
    if (req.path.startsWith('/api/')) return res.status(401).json({ error: 'Session expirée : veuillez vous reconnecter' });
    return res.redirect('/login');
  }

  if (!req.session?.userId) {
    if (req.path.startsWith('/api/')) {
      return res.status(401).json({ error: 'Non autorisé : veuillez vous connecter' });
    }
    return res.redirect('/login');
  }

  /* Éjection immédiate : blacklisté / déconnexion forcée (admin) / session supplantée par une
     connexion plus récente / compte repris depuis un autre navigateur.
     ⚠️ ON APPELLE `_sessionMorte`, ON NE LA RECOPIE PLUS. Cette garde-ci recopiait la règle, et la
     copie avait déjà pris du retard : elle ignorait le contrôle d'appareil ajouté le 21/08, si bien
     qu'un navigateur dépossédé gardait l'accès aux routes API jusqu'à son battement suivant. Une
     règle de sécurité écrite à deux endroits finit toujours par diverger à l'un des deux. */
  const _mort = _sessionMorte(req);
  if (_mort) {
    req.session = null;
    // La RAISON accompagne le 401 : sans elle, le desk renvoyait vers une page de connexion muette
    // et le membre était déconnecté sans jamais savoir pourquoi. Mesuré au banc : selon la route
    // qui répondait en premier, il voyait le message ou pas.
    const _repris = (_mort === 'supplantee' || _mort === 'autre-appareil') ? 'elsewhere' : undefined;
    if (req.path.startsWith('/api/')) return res.status(401).json({ error: 'Session terminée', loggedOut: true, reason: _repris });
    return res.redirect('/login' + (_repris ? '?ended=elsewhere' : ''));
  }
  req.user = req.session.user;
  _noterEmpreinte(req);   // signal de partage, en memoire seule
  next();
}

function requireAdmin(req, res, next) {
  if (req.session?.user?.role !== 'admin') {
    if (req.path.startsWith('/api/')) return res.status(403).json({ error: 'Accès refusé' });
    return res.redirect('/');
  }
  next();
}

// CSRF (défense same-origin, 24/07) — appliqué aux endpoints admin en GET qui MUTENT / ENVOIENT.
// Le cookie de session est SameSite=Lax (bloque déjà <img>/sous-requêtes/POST cross-site) ; le SEUL trou
// résiduel = un GET-qui-mute déclenché par une NAVIGATION top-level depuis un lien piégé (Lax envoie le
// cookie). On le ferme : Sec-Fetch-Site=cross-site → refus. Les fetch same-origin du panel admin passent
// (Sec-Fetch-Site: same-origin) ; les appels NON-navigateur (curl/cron interne, sans ces en-têtes) passent
// aussi — un CSRF exige forcément un navigateur.
const _CSRF_OK_ORIGINS = new Set(['https://desk.datatradingpro.com', 'https://datatradingpro.com', 'https://www.datatradingpro.com', 'http://localhost:3000']);
function requireSameOrigin(req, res, next) {
  const sfs = req.headers['sec-fetch-site'];
  if (sfs) return (sfs === 'same-origin' || sfs === 'same-site' || sfs === 'none') ? next() : res.status(403).json({ error: 'Origine refusée (protection CSRF)' });
  const src = req.headers.origin || req.headers.referer;   // repli navigateurs anciens sans Sec-Fetch-Site
  if (!src) return next();                                  // appelant non-navigateur (curl/cron/interne) → OK
  try { if (_CSRF_OK_ORIGINS.has(new URL(src).origin)) return next(); } catch {}
  return res.status(403).json({ error: 'Origine refusée (protection CSRF)' });
}

// Staff (admin OU agent de support) — accès à la messagerie support, mais PAS à la gestion utilisateurs
function requireSupport(req, res, next) {
  const role = req.session?.user?.role;
  if (role !== 'admin' && role !== 'support') {
    if (req.path.startsWith('/api/')) return res.status(403).json({ error: 'Accès refusé' });
    return res.redirect('/');
  }
  next();
}

app.use(requireAuth);

/* PAGE DE CONNEXION : DÉJÀ CONNECTÉ → ON RENVOIE AU DESK.
   ⚠️ CETTE ROUTE DOIT RESTER AVANT `express.static`. Elle vivait plus bas dans le fichier, donc
   APRÈS le middleware statique qui sert `public/login.html` via `extensions: ['html']` — elle
   n'était jamais atteinte, sur AUCUN des deux chemins. C'était du code mort qui avait l'apparence
   d'une garde ; déplacer cette route sous le statique la re-tuerait silencieusement.
   Les deux chemins sont nommés : `/login` (celui vers lequel le serveur redirige) et `/login.html`
   (accessible directement, déclaré public). Ils étaient troués à l'identique.
   Elle ne remplace pas la garde de login.html : un retour arrière restaure la page depuis le cache
   du navigateur SANS requête réseau — aucune route serveur ne peut l'intercepter. Les deux sont
   nécessaires, celle-ci évite seulement au formulaire d'apparaître une fraction de seconde. */
app.get(['/login', '/login.html'], (req, res) => {
  if (req.session?.userId) return res.redirect('/');
  res.set('Cache-Control', 'no-cache, must-revalidate');
  res.sendFile(path.join(__dirname, 'public', 'login.html'));
});

// extensions: ['html'] → /admin sert admin.html automatiquement (/login est traité juste au-dessus)
app.use(express.static(path.join(__dirname, 'public'), {
  extensions: ['html'],
  // CSS/JS/images : cache navigateur 30 j (gros gain de perf — plus de re-téléchargement de chaque
  // image/feuille à chaque visite). Les CSS/JS sont déjà bustés par ?v=YYYYMMDDx (nouveau déploiement =
  // nouvelle URL = fetch frais) ; pour une image remplacée en place, un Ctrl+F5 (ou l'expiration) la
  // rafraîchit. Pas d'immutable -> le rechargement forcé reste toujours possible.
  maxAge: '30d',
  // Le HTML ne doit JAMAIS être mis en cache : sinon le navigateur garde un index.html avec un
  // ?v= périmé et ne charge jamais le nouveau CSS/JS (cause des « pas à jour » récurrents).
  // On RÉ-ÉCRASE donc l'en-tête posé par maxAge ci-dessus uniquement pour le HTML.
  setHeaders: (res, fp) => { if (/\.html$/i.test(fp)) res.setHeader('Cache-Control', 'no-cache, must-revalidate'); },
}));
app.use(express.json({ limit: '2mb' }));   // 2 Mo : autorise les pièces jointes chat (data URL base64)

// Health check (public) — pour le monitoring / keep-alive (Render, UptimeRobot…)
app.get('/healthz', (_req, res) => res.status(200).json({ ok: true, ts: Date.now() }));
// Version du build courant → le client détecte un nouveau déploiement et propose un rechargement.
// `boot` = heure de demarrage du process. ANGLE MORT COMBLE (06/08) : `v` est le jeton de cache lu dans
// index.html, donc un changement PUREMENT SERVEUR (ex. decaler un envoi planifie) laisse `v` identique —
// impossible de prouver que le conteneur tourne bien sur le nouveau code sans bumper un asset pour rien.
// Avec `boot`, une date de demarrage posterieure au push suffit a le prouver.
app.get('/api/version', (_req, res) => { res.set('Cache-Control', 'no-store'); res.json({ v: BUILD_VERSION, boot: _BOOT_TS }); });

// robots.txt du DESK (Bing WMT 16/07 « meta robots à revoir ») : la page de CONNEXION est indexable
// (requêtes navigationnelles « datatradingpro connexion ») ; tout le reste de l'app reste fermé aux
// crawlers. Sans cette route, /robots.txt tombait dans le gate session → 302 /login = signal sale.
// (Allow plus long que Disallow → prioritaire chez Google ET Bing ; `/$` = la racine seule.)
app.get('/robots.txt', (_req, res) => {
  res.type('text/plain').set('Cache-Control', 'public, max-age=3600')
    .send('User-agent: *\nAllow: /login\nAllow: /$\nDisallow: /\n');
});

app.get('/admin', requireAuth, requireAdmin, (_req, res) => {
  res.set('Cache-Control', 'no-cache, must-revalidate');
  res.sendFile(path.join(__dirname, 'public', 'admin.html'));
});

// Galerie de prévisualisation des emails transactionnels (admin) : voir TOUS les emails rendus,
// avec données d'exemple + l'ordre réel des fournisseurs d'envoi. Aucun email n'est envoyé.
app.get('/admin/emails', requireAuth, requireAdmin, (_req, res) => {
  try { res.type('html').send(mailer.renderEmailGallery()); }
  catch (e) { res.status(500).send('Erreur preview emails: ' + e.message); }
});

// ─── Auth routes ──────────────────────────────────────────────────────────────
// ── Rate-limiting léger en mémoire (anti brute-force / abus, sans dépendance) ──
const _rlBuckets = new Map();   // clé → [timestamps]
function _clientIp(req) {
  return (req.headers['x-forwarded-for'] || '').split(',')[0].trim()
      || req.ip || req.socket?.remoteAddress || 'unknown';
}
function _rateLimited(key, max, windowMs) {
  const now = Date.now();
  const arr = (_rlBuckets.get(key) || []).filter(t => now - t < windowMs);
  arr.push(now);
  _rlBuckets.set(key, arr);
  if (_rlBuckets.size > 5000) {                 // nettoyage anti-fuite mémoire
    for (const [k, v] of _rlBuckets) if (!v.length || now - v[v.length - 1] > windowMs) _rlBuckets.delete(k);
  }
  return arr.length > max;
}

app.post('/api/auth/login', async (req, res) => {
  // Anti brute-force : on ne compte QUE les ÉCHECS d'identifiants (un login réussi — ou un compte
  // suspendu/expiré au bon mot de passe — ne pénalise JAMAIS). Un utilisateur légitime qui recharge/teste
  // n'est donc jamais bloqué. Seuil : 20 échecs / 5 min / IP. (IP réelle via X-Forwarded-For nginx.)
  const _rlKey = 'login:' + _clientIp(req), _rlWin = 5 * 60 * 1000;
  const _fails = (_rlBuckets.get(_rlKey) || []).filter(t => Date.now() - t < _rlWin);
  if (_fails.length >= 20) {
    return res.status(429).json({ error: 'Trop de tentatives de connexion. Réessayez dans quelques minutes.' });
  }
  const { email, password, remember } = req.body || {};
  if (!email || !password) return res.json({ error: 'Email et mot de passe requis' });
  try {
    const user = await auth.verifyLogin(email, password);
    if (!user) {
      _fails.push(Date.now()); _rlBuckets.set(_rlKey, _fails);   // ÉCHEC d'identifiants → compté (vrai brute-force)
      return res.json({ error: 'Email ou mot de passe incorrect' });
    }
    const _renewUrl = process.env.WHOP_RENEW_URL || 'https://whop.com/joined/justonetrader/products/jot-dtp/';
    if (user.suspended) {
      return res.json({ error: 'Votre abonnement n\'est plus actif. Renouvelez-le pour retrouver l\'accès complet au terminal.', renewTitle: 'Abonnement inactif', renewUrl: _renewUrl });
    }
    if (user.expired) {
      const d = new Date(user.expiresAt).toLocaleDateString('fr-FR');
      return res.json({ error: `Votre abonnement a expiré le ${d}. Renouvelez-le dès maintenant pour retrouver l'accès complet au terminal.`, renewTitle: 'Abonnement expiré', renewUrl: _renewUrl });
    }
    req.session.userId = user.id;
    req.session.user   = user;
    req.session.loginAt = Date.now();   // COUPERET 24 h : ancre ABSOLUE du login (le cookie-session est glissant → sans ancre, un utilisateur actif ne serait JAMAIS déconnecté)
    // « Rester connecté » : repousse le couperet a 30 jours pour cette session. Il faut AUSSI etendre
    // la duree du COOKIE — sinon le navigateur le jetterait au bout de 24 h et le couperet allonge ne
    // servirait a rien. cookie-session lit `req.sessionOptions` a l ecriture de la reponse.
    req.session.remember = !!remember;
    if (remember) { try { req.sessionOptions.maxAge = _SESSION_MAX_LONG_MS; } catch (e) {} }
    _forceLogout.delete(String(user.id));   // un login légitime lève un éventuel ordre de déconnexion (kick ponctuel)
    /* Session UNIQUE par compte : jeton neuf → invalide les sessions précédentes (anti-partage).
       ⚠️ LE STAFF N'EST PLUS EXEMPTÉ (21/08, demande user : « qu'on ne puisse pas se connecter à
       deux sur un même compte »). L'exemption d'origine rendait la règle INVÉRIFIABLE pour qui la
       testait : on essaie naturellement avec SON compte, qui est admin, on voit deux sessions
       cohabiter, et on en conclut que rien ne marche. Mesuré au banc avant correction : client
       verrouillé, admin et support non. La règle vaut désormais pour tout le monde.
       `DTP_SESSION_UNIQUE_STAFF=0` rétablit l'ancien comportement sans toucher au code : un
       administrateur qui travaille sur deux postes se déconnecterait lui-même en permanence, et il
       faut pouvoir revenir en arrière sans redéployer. */
    if (_SESSION_UNIQUE_STAFF || (user.role !== 'admin' && user.role !== 'support')) {
      const _stok = require('crypto').randomUUID();
      req.session.stoken = _stok;
      _sessionEpoch.set(String(user.id), _stok);
      _sessEpochSauver();   // le registre doit survivre au prochain redeploiement
      /* Le WebSocket vit des heures : sans cette boucle, la session ejectee du desk continuerait de
         recevoir le fil temps reel jusqu a ce que l onglet soit ferme. On coupe les sockets du meme
         compte dont le jeton n est plus le bon. */
      try {
        wss.clients.forEach((c) => {
          if (c._uid === String(user.id) && c._stoken && c._stoken !== _stok) {
            try { c.close(1008, 'session supplantée'); } catch (e) {}
          }
        });
      } catch (e) {}
    }
    res.json({ ok: true, role: user.role });
  } catch (e) {
    console.error('[Auth] login error:', e.message);
    res.status(500).json({ error: 'Erreur serveur' });
  }
});

app.post('/api/auth/logout', (req, res) => {
  req.session = null;
  res.json({ ok: true });
});

// Mot de passe oublié : génère un MDP temporaire et l'envoie par email.
// Réponse toujours { ok:true } (ne révèle pas si l'email existe).
const _recentForgot = new Map();            // email → ts du dernier reset RÉELLEMENT émis
const FORGOT_COOLDOWN_MS = 2 * 60 * 1000;   // 2 min : un 2e « mot de passe oublié » trop rapproché ne régénère PAS
app.post('/api/auth/forgot-password', (req, res) => {
  const email = (req.body?.email || '').toLowerCase().trim();
  res.json({ ok: true });   // réponse IMMÉDIATE (UX instantanée + anti-énumération)
  // Anti-abus : max 5 demandes / 10 min / IP (au-delà, on ignore silencieusement)
  if (_rateLimited('forgot:' + _clientIp(req), 5, 10 * 60 * 1000)) return;
  if (!email) return;
  // VERROU PAR EMAIL (posé SYNCHRONEMENT, avant tout await) : un double-clic générait DEUX MDP
  // temporaires différents — le 2e changePassword écrasait le MDP stocké — tandis que l'anti-doublon
  // <12s du mailer SUPPRIMAIT le 2e email. Résultat : l'utilisateur recevait le MDP n°1 mais la base
  // contenait le n°2 → « identifiants incorrects ». On ne régénère donc qu'UNE fois par fenêtre :
  // l'email déjà envoyé reste valide. (Node mono-thread : set avant le 1er await => atomique.)
  if (Date.now() - (_recentForgot.get(email) || 0) < FORGOT_COOLDOWN_MS) {
    console.log(`[Auth] forgot ignoré (reset déjà émis <2 min) → ${email}`);
    return;
  }
  _recentForgot.set(email, Date.now());
  if (_recentForgot.size > 5000) _recentForgot.clear();   // garde-fou mémoire
  // Le travail (lookup + hash bcrypt + update DB + email) se fait en arrière-plan, après la réponse.
  (async () => {
    try {
      const users = await auth.getAllUsers();
      const u = users.find(x => (x.email || '').toLowerCase() === email);
      if (u) {
        // SÉCURITÉ : réinitialisation RÉSERVÉE aux abonnements ACTIFS (staff toujours OK). Un compte
        // suspendu/expiré reçoit un e-mail « abonnement inactif » (aucun mot de passe n'est régénéré).
        const _staff = u.role === 'admin' || u.role === 'support';
        const _expMs = u.expires_at ? new Date(u.expires_at).getTime() : null;
        const _GRACE = 24 * 60 * 60 * 1000;   // même tolérance que la connexion (renouvellement en cours)
        const _active = _staff || (u.active !== false && (!_expMs || _expMs + _GRACE >= Date.now()));
        if (_active) {
          const temp = require('crypto').randomBytes(9).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 10) + 'A1';
          await auth.changePassword(u.id, temp);
          mailer.sendPasswordReset({ to: u.email, name: u.name, password: temp }).catch(() => {});
          console.log(`[Auth] Mot de passe réinitialisé (forgot) → ${u.email}`);
        } else {
          mailer.sendForgotNoSub({ to: u.email, name: u.name }).catch(() => {});
          console.log(`[Auth] forgot REFUSÉ (abonnement inactif) → ${u.email} : e-mail de réactivation envoyé`);
        }
      } else {
        _recentForgot.delete(email);   // email inexistant → on libère le verrou (aucun reset effectué)
      }
    } catch (e) { _recentForgot.delete(email); console.error('[Auth] forgot-password error:', e.message); }
  })();
});

app.get('/api/auth/me', async (req, res) => {
  if (!req.session?.userId) return res.json({ loggedIn: false });
  // COUPERET 24 h (le heartbeat du desk ~20 s passe ICI, pas par requireAuth — /api/auth/ est public) :
  // session plus vieille que 24 h → déconnexion immédiate sur TOUTES les plateformes (web/app/mobile).
  if (_sessionExpired(req)) { req.session = null; return res.json({ loggedIn: false, reason: 'expired' }); }
  try {
    // Toujours relire depuis la DB → les changements admin (active, plan…) sont immédiatement reflétés
    const fresh = await auth.getUserById(req.session.userId);
    if (!fresh) { req.session = null; return res.json({ loggedIn: false }); }
    // Éjection : blacklisté, suspendu (client non-actif), déconnexion admin, ou session supplantée par une
    // connexion plus récente (session unique par compte) → logout immédiat.
    const _mep = _sessionEpoch.get(String(req.session.userId));
    // Même garde que dans requireAuth : une session sans jeton est ANTÉRIEURE au mécanisme, elle ne
    // doit pas être éjectée par la restauration du registre au démarrage.
    const _tokenSupplante = !!(_mep && req.session.stoken && _mep !== req.session.stoken);

    /* SECOND VERROU : le navigateur. Le desk annonce son identifiant à CHAQUE battement, mais ne
       RÉCLAME le compte qu'au chargement de la page (en-tête `x-dtp-appareil-neuf`). Sans cette
       distinction, deux navigateurs se réclameraient le compte toutes les 20 secondes et se
       chasseraient l'un l'autre sans fin. */
    const _dev = _devDeLaRequete(req), _uidS = String(req.session.userId);
    let _devSupplante = false;
    if (_dev && String(req.headers['x-dtp-appareil-neuf'] || '') === '1') {
      if (_devReclamer(_uidS, _dev)) _fermerSocketsAppareil(_uidS, _dev);   // reprise : on coupe l'ancien flux
    } else if (_dev) {
      const _det = _sessionDevice.get(_uidS);
      _devSupplante = !!(_det && _det.dev !== _dev);
    }
    const _superseded = _tokenSupplante || _devSupplante;
    if (_forceLogout.has(String(req.session.userId)) || auth.isEmailBlacklisted(fresh.email)
        || (fresh.role !== 'admin' && fresh.role !== 'support' && fresh.active === false) || _superseded) {
      req.session = null; return res.json({ loggedIn: false, reason: _superseded ? 'elsewhere' : undefined });
    }
    // (Audit 28/07) Échéance dépassée AU-DELÀ de la grâce de 24 h (même règle que le login) → la
    // session en cours est éjectée aussi. Avant : un compte marqué expiré gardait son desk ouvert
    // tant que sa session vivait, seule la reconnexion était bloquée.
    if (fresh.role !== 'admin' && fresh.role !== 'support' && fresh.expires_at) {
      const _expT = new Date(fresh.expires_at).getTime();
      if (Number.isFinite(_expT) && _expT + 24 * 3600e3 < Date.now()) { req.session = null; return res.json({ loggedIn: false, reason: 'expired' }); }
    }
    const expiresAt = fresh.expires_at || null;
    const isTrial = _isTrialAccount(fresh);
    // Libellé du badge profil : « TYPE · CADENCE » (ex. « Professionnel · Mensuel ») — remplace le
    // libellé codé en dur du desk. Type depuis le compte, cadence dérivée/override (_cadOf).
    const _tl = fresh.role !== 'client' ? '' : (_isFriend(fresh) ? 'Amis' : (isTrial ? 'Essai gratuit' : 'Professionnel'));
    const _cl = _CAD_LBL[_cadOf(fresh)] || '';
    const planLabel = _tl ? (_cl && _tl !== 'Essai gratuit' ? _tl + ' · ' + _cl : _tl) : 'Professionnel';
    const user = { id: fresh.id, email: fresh.email, name: fresh.name, role: fresh.role, plan: fresh.plan, active: !!fresh.active, expiresAt, isTrial, planLabel };
    req.session.user = user; // maintenir la session à jour
    // loginAt = ancre ABSOLUE du login (déjà posée pour le couperet 24 h). Exposée au front pour
    // qu'il distingue « nouvelle connexion » de « rechargement de page » — sessionStorage ne sait
    // pas faire la différence. C'est un horodatage, pas un secret.
    res.json({ loggedIn: true, user, loginAt: req.session.loginAt || 0, feat: _newFeat });
  } catch {
    // Fallback si DB inaccessible : utiliser la session
    res.json({ loggedIn: true, user: req.session.user, loginAt: req.session.loginAt || 0, feat: _newFeat });
  }
});

// ── Historique « Recent Searches » de la recherche symbole, PERSISTANT PAR COMPTE ──
// Stockage léger via le KV durable Supabase (auth.aiCacheSet/Get), clé symrecent:<userId> → suit la
// reconnexion (même sur un autre appareil). Valeur = { recent: [<6 codes de paire>] }. 0 schéma, 0 charge notable.
const _SYM_RX = /^[A-Z]{6}$/;
app.get('/api/sym-recent', async (req, res) => {
  if (!req.session?.userId) return res.json({ recent: [] });
  try {
    const v = await auth.aiCacheGet('symrecent:' + req.session.userId);
    const recent = (v && Array.isArray(v.recent)) ? v.recent.filter(p => typeof p === 'string' && _SYM_RX.test(p)).slice(0, 8) : [];
    res.json({ recent });
  } catch { res.json({ recent: [] }); }
});
app.post('/api/sym-recent', async (req, res) => {
  if (!req.session?.userId) return res.status(401).json({ ok: false });
  try {
    const arr = Array.isArray(req.body?.recent) ? req.body.recent : [];
    const recent = arr.filter(p => typeof p === 'string' && _SYM_RX.test(p)).slice(0, 8);
    await auth.aiCacheSet('symrecent:' + req.session.userId, { recent });
    res.json({ ok: true, recent });
  } catch { res.status(500).json({ ok: false }); }
});

// ── Rapports Analyst « LUS » (cartes grisées), PERSISTANT PAR COMPTE (KV durable Supabase, modèle
