function buildUSOpening({ dateStr, s, reportType }) {
  const bullets = [];
  bullets.push(`US Opening : ${s.all.length} events tracked · ${dateStr}`);
  _pushBullets(bullets, 'Fed & Central Banks', s.cb, 3);
  _pushBullets(bullets, 'US Data', s.hdata.length ? s.hdata : s.data, 3);
  _pushBullets(bullets, 'Geopolitical', s.geo, 2);
  _pushBullets(bullets, 'Trade', s.trade, 2);
  _pushBullets(bullets, 'Equity & FX Outlook', s.fx, 2);
  _pushBullets(bullets, 'Commodities', s.nrg, 2);
  return { subtitle: _briefingSubtitle(reportType, s, ['Fed','BoC']), bullets, tags: _briefingTags(s, ['US Opening','USD']) };
}

function buildAsiaOpening({ dateStr, s, reportType }) {
  const bullets = [];
  bullets.push(`Asia Opening : ${s.all.length} events in review · ${dateStr}`);
  _pushBullets(bullets, 'BoJ / RBA / PBOC Watch', s.cb, 3);
  _pushBullets(bullets, 'Asian Session Headlines', s.asian, 3);
  _pushBullets(bullets, 'Overnight Data', s.hdata.length ? s.hdata : s.data, 3);
  _pushBullets(bullets, 'Geopolitical', s.geo, 2);
  _pushBullets(bullets, 'Commodities', s.nrg, 2);
  _pushBullets(bullets, 'Trade', s.trade, 1);
  // Titre façon DTP (généré après la clôture NY, à l'ouverture Asie-Pacifique)
  const subtitle = `DTP Daily Asia-Pac Opening News - ${dateStr}`;
  return { subtitle, bullets, tags: _briefingTags(s, ['Asia Opening', 'JPY', 'AUD']) };
}

// Récap de la séance Asie-Pacifique. Même moule que Londres et New York — seuls changent les
// accents : banques centrales de la zone (BoJ, RBA, RBNZ, PBoC), données régionales, devises JPY/
// AUD/NZD/CNH. Assemblage par règles, aucun appel IA : il sort même quand le quota est épuisé.
// ── RÉCAPS DE SÉANCE : LA STRUCTURE DU RÉCAP QUOTIDIEN (14/08, demande user) ──────────────────
// Les trois séances déclinaient chacune SES propres rubriques, en anglais et différentes entre
// elles (« BoJ / RBA / RBNZ / PBoC », « European Data Outcomes », « Commodities », « Trade »…).
// Dans l'onglet ANALYSTES ces rapports se lisent à la suite dans la même journée : le lecteur
// passait donc du récap de séance au récap quotidien sans retrouver ses repères.
// Les trois adoptent les catégories du quotidien — GÉOPOLITIQUE · MACRO · À SURVEILLER — dans le
// même ordre et en français. Le CONTENU reste propre à chaque séance (la BoJ ne remonte pas dans
// le récap de Londres) : c'est la GRAMMAIRE qui devient commune, pas les données.
//   · « Macro » regroupe banques centrales ET données publiées : le quotidien les traite ensemble,
//     les séparer ici recréerait l'écart qu'on vient de supprimer ;
//   · « Analyse de séance » porte le MARCHÉ (devises, matières premières, commerce). C'est le
//     pendant, pour une séance unique, de la rubrique « Analyse par session » du quotidien.
//   · « À surveiller » n'est PAS produite ici, et c'est délibéré : dans le récap quotidien elle est
//     STRICTEMENT PROSPECTIVE (le rendez-vous à venir + pourquoi il compte). Ces builders ne
//     disposent d'aucune source d'événements futurs : la remplir avec le FX et les matières
//     premières de la séance écoulée, comme je l'avais fait le 14/08, lui donnait le même nom que
//     dans le quotidien mais PAS le même sens, ce qui est pire qu'une rubrique absente. La
//     segmentation IA, elle, la crée quand le texte évoque de vraies échéances.
function buildAsiaRecap({ dateStr, s, reportType }) {
  const bullets = [];
  bullets.push(`Récap séance Asie : ${s.all.length} éléments suivis · ${dateStr}`);
  _pushBullets(bullets, 'Géopolitique', s.geo, 3);
  _pushBullets(bullets, 'Macro', [...s.cb, ...(s.hdata.length ? s.hdata : s.data)], 4);
  _pushBullets(bullets, 'Analyse de séance', [...s.fx, ...s.asian, ...s.nrg, ...s.trade], 4);
  return { subtitle: _briefingSubtitle(reportType, s, ['BoJ', 'RBA', 'RBNZ', 'PBoC']), bullets, tags: _briefingTags(s, ['Asia Recap', 'JPY', 'AUD']) };
}

