function _infoTitlePrompt(headline) {
  return `Tu es éditeur d'un terminal financier professionnel. Le TITRE BRUT ci-dessous reprend des propos personnels/politiques (souvent un post de réseau social), SANS donnée de marché.
Écris UNE ligne, un titre FR NEUTRE et FACTUEL qui EXPLIQUE de quoi il s'agit : qui s'exprime (seulement si clairement identifiable) et sur quel sujet.
RÈGLES STRICTES :
- purement factuel et neutre : aucun jugement, ne reprends NI le ton NI les superlatifs de l'auteur ;
- n'ajoute AUCUN fait absent du titre, n'invente rien, ne prends parti pour personne ;
- si l'auteur n'est pas identifiable avec certitude, décris seulement le SUJET sans nommer de personne ;
- 6 à 12 mots, sans guillemets, sans point final.
TITRE BRUT : "${String(headline || '').slice(0, 400)}"
Titre FR :`;
}
function _cleanInfoTitle(s) {
  let t = String(s || '').split('\n').map(x => x.trim()).filter(Boolean)[0] || '';
  t = t.replace(/^[-•*\d.)\s]+/, '').replace(/^["“”'`]+|["“”'`.]+$/g, '').replace(/\s+/g, ' ').trim();
  if (t.length < 6 || t.length > 120) return '';
  return t;
}
async function _enrichInfoTitles() {
  if (_aiInfoTitleBusy) return;
  const hasAI = (ai.hasAnthropic && ai.hasAnthropic()) || !!(process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY);
  if (!hasAI) return;
  _aiInfoTitleBusy = true;
  try {
    const today = _aiDay();
    if (_aiAnaDay !== today) { _aiAnaDay = today; _aiAnaDayCount = 0; }        // partage le compteur/plafond de l'enrichissement analyse
    let perCycle = 2;
    try { if ((typeof ai.shouldThrottle === 'function' && ai.shouldThrottle()) || _aiUsersIdle()) perCycle = 1; } catch {}
    for (const item of allNews) {
      if (!item || !item._infoQuote || item._infoTitle) continue;              // pas concerné / déjà fait
      const ck = 'infotitle:v1:' + item.id;
      if (_infoTitleCache.has(ck)) {
        const v = _infoTitleCache.get(ck);
        if (v) { item._infoTitle = v; item._itV1 = true; try { broadcast({ type: 'news_update', items: [item], total: allNews.length }); } catch {} }
        continue;
      }
      let cached = null; try { cached = await auth.aiCacheGet(ck); } catch {}
      if (typeof cached === 'string') {
        _infoTitleCache.set(ck, cached);
        if (cached) { item._infoTitle = cached; item._itV1 = true; try { broadcast({ type: 'news_update', items: [item], total: allNews.length }); } catch {} }
        continue;
      }
      if (perCycle <= 0 || _aiAnaDayCount >= AI_ANALYSE_DAILY_MAX) break;
      perCycle--; _aiAnaDayCount++;
      try {
        const out = await aiSmart('news', _infoTitlePrompt(item.headline), 60, { important: true });   // RÈGLE : aiSmart('news') EXIGE important:true (sinon refus budget silencieux)
        const title = _cleanInfoTitle(out);
        _infoTitleCache.set(ck, title);                                        // cache même vide (échec = pas de re-tentative en boucle)
        if (_infoTitleCache.size > 1500) _infoTitleCache.delete(_infoTitleCache.keys().next().value);
        _saveJsonMap(path.join(_CACHE_DIR, 'cache_infotitle.json'), _infoTitleCache);
        if (title) auth.aiCacheSet(ck, title).catch(() => {});
        if (title) { item._infoTitle = title; item._itV1 = true; try { broadcast({ type: 'news_update', items: [item], total: allNews.length }); } catch {} }
      } catch { /* budget épuisé → le client garde le repli déterministe */ }
    }
  } finally { _aiInfoTitleBusy = false; }
}
function _mergeAiTags(item, aiTags) {
  // catégorie d'abord (souvent masquée par le front), puis tags IA nets — au plus 4
  return [...new Set([item.category, ...(aiTags || [])])].slice(0, 4);
}
async function _smartTagNews() {
  if (_aiTagBusy) return;
  const hasAI = (ai.hasAnthropic && ai.hasAnthropic()) || !!(process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY);
  if (!hasAI) return;
  _aiTagBusy = true;
  try {
    const today = _aiDay();
    if (_aiTagDay !== today) { _aiTagDay = today; _aiTagDayCount = 0; }   // reset journalier
    let perCycle = 1;                                                     // 1 génération IA par passage
    for (const item of allNews) {
      if (!item || item._briefing || item._aiTagged) continue;
      if (item.priority !== 'high') continue;                            // IMPORTANTES uniquement
      if (Date.now() - item.timestamp > 6 * 60 * 60 * 1000) continue;    // récentes uniquement
      // 1) cache chaud
      if (_aiTagCache.has(item.id)) { item.tags = _mergeAiTags(item, _aiTagCache.get(item.id)); item._aiTagged = true; continue; }
      // 2) cache durable (Supabase) — pas de requête IA
      let cached = null; try { cached = await auth.aiCacheGet('tag:' + item.id); } catch {}
      if (Array.isArray(cached)) { _aiTagCache.set(item.id, cached); item.tags = _mergeAiTags(item, cached); item._aiTagged = true; continue; }
      // 3) génération IA (bornée par le cap journalier + 1/cycle)
      if (perCycle <= 0 || _aiTagDayCount >= AI_TAG_DAILY_MAX) break;
      perCycle--; _aiTagDayCount++;
      try {
        const out = await aiSmart('news',
          `From this EXACT list only: ${AI_TAG_VOCAB.join(', ')}, pick the 0 to 3 tags that TRULY describe this market news. ` +
          `If none clearly apply, answer NONE. Answer with just the chosen tags comma-separated (or NONE), nothing else.\nNews: ${item.headline}`,
          40, { important: true, claudeOverBudget: false });
        const up = AI_TAG_VOCAB.map(v => v.toUpperCase());
        const picked = /NONE/i.test(String(out)) ? []
          : String(out).split(/[,\n;]/).map(s => s.trim()).filter(Boolean)
              .map(s => AI_TAG_VOCAB[up.indexOf(s.toUpperCase())]).filter(Boolean).slice(0, 3);
        _aiTagCache.set(item.id, picked);
        if (_aiTagCache.size > 3000) _aiTagCache.delete(_aiTagCache.keys().next().value);   // cap mémoire (anti-OOM)
        item.tags = _mergeAiTags(item, picked); item._aiTagged = true;
        auth.aiCacheSet('tag:' + item.id, picked).catch(() => {});
      } catch { /* budget épuisé / pas de clé → on garde les tags mots-clés (déjà précis) */ }
    }
  } finally { _aiTagBusy = false; }
}

// ─── Main refresh loop — ForexFactory + FinancialJuice ───────────────────────

async function refreshNews() {
  console.log(`\n[${new Date().toLocaleTimeString()}] Refreshing news sources...`);

  const [fjItems, ffCalItems, ffNewsItems, rssItems] = await Promise.allSettled([
    scrapeFinancialJuice(),
    scrapeForexFactory(),
    scrapeForexFactoryNews(),
    fetchAllRSS(),
  ]).then(rs => rs.map(r => r.status === 'fulfilled' && Array.isArray(r.value) ? r.value : []));

  // Calendar events go to their own store — NOT mixed into the news feed
  if (ffCalItems.length > 0) allCalendar = ffCalItems;
  // Actuals : source PRINCIPALE TradingView (HTTP, sans Cloudflare) + complément depuis nos news.
  _refreshTVActuals().catch(() => {});
  try { _backfillActualsFromNews(); } catch {}

  // Inject released calendar events WITH actual values into the news feed.
  // Gap qualité #1 : inclure aussi les données MEDIUM-impact chiffrées (ex. Michigan Consumer Sentiment
  // Final 50.7 vs Exp 49.3 — le coeur d'un feed institutionnel), pas seulement High. La valeur Actual|Exp|Prev
  // est déjà formatée ; le plafond DATA_CATS_CAP (8/2min hors tier-1) borne le volume Medium. _highImpact
  // reste réservé au High (via upgradeItemPriority), donc Medium passe en priorité normale (pas de pastille rouge).
  const calReleased = ffCalItems.filter(i =>
    i.description && i.description.includes('Actual:') &&
    i.timestamp < Date.now() &&
    (i.priority === 'high' || i.impact === 'Medium')
  );

  // News feed: FJ + FF-News + high-impact released calendar events + RSS multi-sources
  const added = mergeItems([...fjItems, ...ffNewsItems, ...calReleased, ...rssItems]);
  const count = added.length;
  console.log(`  [FJ:${fjItems.length} FF-Cal:${ffCalItems.length}→cal FF-News:${ffNewsItems.length} RSS:${rssItems.length}] +${count} new (total: ${allNews.length})`);

  if (count > 0 || isFirstLoad) {
    if (isFirstLoad) {
      isFirstLoad = false;
      broadcast(_initialPayload());
    } else {
      broadcast({ type: 'news_update', items: added, total: allNews.length });
    }
  }

  // Analyse IA PRE-CALCULEE = la TRADUCTION FR affichee au depliage -> lancee a CHAQUE cycle (60s) pour que le
  // francais apparaisse VITE (bornee par AI_ANALYSE_DAILY_MAX + cooldowns providers + pression sante Phase 3).
  _enrichAnalyses().catch(() => {});
  // Titre explicatif IA des news « propos/citation » hors marché (_infoQuote) — meme cadence, cap partage.
  _enrichInfoTitles().catch(() => {});
  // Pré-traduction FR des dépêches IMPORTANTES sans analyse (priorité background : cède en premier).
  _enrichDescriptionsFr().catch(() => {});
  // « Impact marché » sur les statistiques tier-1 du fil (2/cycle, plafond journalier propre, cache durable).
  _enrichImpacts().catch(() => {});
  // Explication des news de PROPOS (citations politiques/banque centrale) : 2/cycle, plafond propre,
  // cache durable. Préchauffée en fond, jamais au clic : le panneau doit se peindre en une fois.
  _enrichProposCtx().catch(() => {});
  // Affinage des TAGS (moins urgent) : reste throttle 1 cycle sur 3 pour lisser le RPM. Tag heuristique deja affiche.
  globalThis._newsAiTick = (globalThis._newsAiTick || 0) + 1;
  if (globalThis._newsAiTick % 3 === 0) _smartTagNews().catch(() => {});
  // ANTICIPATION calendrier : dès qu'une news de résultat arrive, on remplit l'actual de l'événement
  // correspondant (sans attendre l'ouverture de l'onglet calendrier) → on récupère tout au fil de l'eau.
  try { _backfillActualsFromNews(); } catch {}
}

// ─── WebSocket ───────────────────────────────────────────────────────────────

wss.on('connection', (ws, req) => {
  // Restreint le flux WS aux origines autorisées (prod + ALLOWED_ORIGINS configuré) → anti-leech.
  if (process.env.NODE_ENV === 'production' && ALLOWED_ORIGINS.length) {
    const origin = req?.headers?.origin || '';
    const ok = !origin || ALLOWED_ORIGINS.some(o => origin === o || origin.endsWith(o));
    if (!ok) { try { ws.close(1008, 'origin not allowed'); } catch {} return; }
  }
  /* ⚠️ AUTHENTIFICATION DU FLUX (19/08). Ce gestionnaire n en avait AUCUNE : il envoyait d emblee
     les 200 dernieres actualites, les rapports Analystes et la recherche bancaire a n importe quelle
     connexion. La seule barriere etait le controle d origine ci-dessus, qui (a) accepte
     explicitement une origine ABSENTE — donc tout client hors navigateur — et (b) ne s active que si
     ALLOWED_ORIGINS est renseigne, ce qui n etait PAS le cas en production (verifie sur le serveur).
     Le coeur du produit vendu etait donc lisible sans compte.
     On applique ici la MEME regle que requireAuth, ni plus ni moins. Seul le desk ouvre un
     WebSocket (public/js/app.js) : la landing passe par des routes REST, elle n est pas touchee. */
  const _uid = _wsUserIdFromReq(req);   // execute le middleware de session : req.session est peuple
  const _mortWs = _sessionMorte(req);
  if (_mortWs) {
    try { ws.close(1008, 'session ' + _mortWs); } catch (e) {}
    return;
  }
  console.log(`[WS] Client connected (${wss.clients.size})`);

  const _role = (req.session && req.session.user && req.session.user.role) || null;
  // Le jeton tague le socket : une connexion plus recente pourra fermer celui-ci (voir le login).
  // `_dev` : le navigateur d'où vient ce flux (paramètre `?a=`, un WebSocket ne porte pas d'en-tête).
  // Il permet de couper CE socket-ci quand un autre navigateur reprend le compte.
  ws._uid = _uid; ws._role = _role; ws._stoken = req.session.stoken || null; ws._dev = _devDeLaRequete(req);
  if (_uid) { _onlineUsers.set(_uid, (_onlineUsers.get(_uid) || 0) + 1); _stampSeen(_uid); }   // present -> derniere presence = maintenant

  ws.send(JSON.stringify(_initialPayload(req.session?.user?.role === 'admin')));   // ⚠️ envoi DIRECT : il ne passe pas par broadcast(), donc il doit filtrer lui-même
  // Envoyer aussi les session wraps et bank research au moment de la connexion
  if (_swCache.length > 0) ws.send(JSON.stringify({ type: 'sw_update', items: _swCache }));
  if (_brCache.length > 0) ws.send(JSON.stringify({ type: 'br_update', items: _brCache }));

  ws.on('error', err => console.error('[WS]', err.message));
  ws.on('close', () => {
    if (_uid) { const n = (_onlineUsers.get(_uid) || 1) - 1; if (n <= 0) { _onlineUsers.delete(_uid); _stampSeen(_uid); } else _onlineUsers.set(_uid, n); }   // dernier onglet fermé → « vu » = maintenant
    console.log(`[WS] Disconnected (${wss.clients.size} left)`);
  });
});

